  const result=this.renderer.draw(image,lm,mode,amount,beauty,mirror),w=this.surface.width,h=this.surface.height;
  if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h;const stage=this.canvas.closest('.stage');if(stage)stage.style.aspectRatio=w+'/'+h;}
  const g=this.context;g.setTransform(1,0,0,1,0,0);g.globalAlpha=1;g.globalCompositeOperation='source-over';g.drawImage(this.surface,0,0);
