 if(lastMetrics){const dt=Math.max(.016,(t-lastMetrics.t)/1000),speed=Math.hypot(mid.x-lastMetrics.x,mid.y-lastMetrics.y)/dist/dt;motion=Math.max(0,Math.min(1,(5-speed)/3));}
